@import "tailwindcss";
@import "uniwind";

@theme {
  --color-background: hsl(46.7 100.0% 98.2%);
  --color-foreground: hsl(47.1 56.8% 14.5%);
  --color-card: hsl(45.0 100.0% 99.2%);
  --color-card-foreground: hsl(47.1 56.8% 14.5%);
  --color-popover: hsl(45.0 100.0% 99.2%);
  --color-popover-foreground: hsl(47.1 56.8% 14.5%);
  --color-primary: hsl(213.2 100.0% 43.9%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(42.2 62.7% 88.4%);
  --color-secondary-foreground: hsl(47.1 56.8% 14.5%);
  --color-muted: hsl(42.2 62.7% 88.4%);
  --color-muted-foreground: hsl(44.6 31.5% 48.6%);
  --color-accent: hsl(46.8 88.1% 86.9%);
  --color-accent-foreground: hsl(45.2 100.0% 23.9%);
  --color-destructive: hsl(349.9 80.2% 49.4%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(45.0 57.1% 86.3%);
  --color-input: hsl(43.8 56.8% 78.2%);
  --color-ring: hsl(213.2 100.0% 43.9%);
  --radius-lg: 0.5rem;
  --radius-md: calc(0.5rem - 2px);
  --radius-sm: calc(0.5rem - 4px);
}

@layer theme {
  :root {
    @variant light {
  --color-background: hsl(46.7 100.0% 98.2%);
  --color-foreground: hsl(47.1 56.8% 14.5%);
  --color-card: hsl(45.0 100.0% 99.2%);
  --color-card-foreground: hsl(47.1 56.8% 14.5%);
  --color-popover: hsl(45.0 100.0% 99.2%);
  --color-popover-foreground: hsl(47.1 56.8% 14.5%);
  --color-primary: hsl(213.2 100.0% 43.9%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(42.2 62.7% 88.4%);
  --color-secondary-foreground: hsl(47.1 56.8% 14.5%);
  --color-muted: hsl(42.2 62.7% 88.4%);
  --color-muted-foreground: hsl(44.6 31.5% 48.6%);
  --color-accent: hsl(46.8 88.1% 86.9%);
  --color-accent-foreground: hsl(45.2 100.0% 23.9%);
  --color-destructive: hsl(349.9 80.2% 49.4%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(45.0 57.1% 86.3%);
  --color-input: hsl(43.8 56.8% 78.2%);
  --color-ring: hsl(213.2 100.0% 43.9%);
    }

    @variant dark {
  --color-background: hsl(48.0 58.8% 6.7%);
  --color-foreground: hsl(46.0 64.2% 86.9%);
  --color-card: hsl(46.5 44.9% 13.5%);
  --color-card-foreground: hsl(46.0 64.2% 86.9%);
  --color-popover: hsl(47.0 51.1% 8.8%);
  --color-popover-foreground: hsl(46.0 64.2% 86.9%);
  --color-primary: hsl(209.4 99.1% 57.3%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(47.1 46.7% 11.8%);
  --color-secondary-foreground: hsl(46.0 64.2% 86.9%);
  --color-muted: hsl(47.1 46.7% 11.8%);
  --color-muted-foreground: hsl(43.0 22.7% 45.7%);
  --color-accent: hsl(48.5 79.7% 11.6%);
  --color-accent-foreground: hsl(47.9 100.0% 60.0%);
  --color-destructive: hsl(353.0 90.4% 59.2%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(46.5 44.9% 13.5%);
  --color-input: hsl(45.0 42.3% 20.4%);
  --color-ring: hsl(209.4 99.1% 57.3%);
    }
  }
}
